package com.mengzhihua.crm.service.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.service.entity.*;import com.mengzhihua.crm.service.service.CaseService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/cases") public class CaseController{private final CaseService s;public CaseController(CaseService x){s=x;}@GetMapping public Result<PageResult<CrmCase>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword,@RequestParam(required=false)Enums.CaseStatus status,@RequestParam(required=false)Enums.CasePriority priority,@RequestParam(required=false)Long accountId,@RequestParam(required=false)Boolean overdue){return Result.ok(s.list(page,size,keyword,status,priority,accountId,overdue));}@GetMapping("/{id}")public Result<CrmCase> get(@PathVariable Long id){return Result.ok(s.get(id));}@PostMapping public Result<CrmCase> add(@RequestBody CrmCase x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<CrmCase> edit(@PathVariable Long id,@RequestBody CrmCase x){x.setId(id);return Result.ok(s.save(x));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}@PutMapping("/{id}/status")public Result<CrmCase> status(@PathVariable Long id,@RequestBody Map<String,Object>b){return Result.ok(s.status(id,b));}@PutMapping("/{id}/escalate")public Result<CrmCase> escalate(@PathVariable Long id){return Result.ok(s.escalate(id));}@PutMapping("/{id}/assign")public Result<CrmCase> assign(@PathVariable Long id,@RequestBody Map<String,String>b){CrmCase c=s.get(id);c.setOwner(b.get("owner"));return Result.ok(s.save(c));}@GetMapping("/{id}/comments")public Result<List<CaseComment>> comments(@PathVariable Long id){return Result.ok(s.commentList(id));}@PostMapping("/{id}/comments")public Result<CaseComment> comment(@PathVariable Long id,@RequestBody CaseComment c){return Result.ok(s.comment(id,c));}}
